module tb_TopModule;
    logic a;
    logic b;
    logic out_assign;
    logic out_alwaysblock;

    TopModule dut (
        .a(a),
        .b(b),
        .out_assign(out_assign),
        .out_alwaysblock(out_alwaysblock)
    );

    initial begin
        // Test all input combinations for an AND gate
        a = 0; b = 0;
        #10;
        if (out_assign !== 0 || out_alwaysblock !== 0) begin
            $display("SELFTEST FAIL: a=0, b=0 -> assign=%b, always=%b", out_assign, out_alwaysblock);
            $finish;
        end

        a = 0; b = 1;
        #10;
        if (out_assign !== 0 || out_alwaysblock !== 0) begin
            $display("SELFTEST FAIL: a=0, b=1 -> assign=%b, always=%b", out_assign, out_alwaysblock);
            $finish;
        end

        a = 1; b = 0;
        #10;
        if (out_assign !== 0 || out_alwaysblock !== 0) begin
            $display("SELFTEST FAIL: a=1, b=0 -> assign=%b, always=%b", out_assign, out_alwaysblock);
            $finish;
        end

        a = 1; b = 1;
        #10;
        if (out_assign !== 1 || out_alwaysblock !== 1) begin
            $display("SELFTEST FAIL: a=1, b=1 -> assign=%b, always=%b", out_assign, out_alwaysblock);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
